module resource_claim (\n    input clk,\n    input rst_n,\n    input start,\n    \n    input [3:0] node_count,\n    input [3:0] iron_count,\n    input [3:0] coal_count,\n    \n    input [3:0] iron_nodes [0:3],\n    input [3:0] coal_nodes [0:3],\n    \n    input [15:0] adjacency [0:15],\n    \n    output reg [7:0] result,\n    output reg done,\n    output reg impossible\n);\n\nlocalparam [2:0] \n    IDLE      = 3'd0,\n    BFS_IRON  = 3'd1,\n    BFS_COAL  = 3'd2,\n    COMPUTE   = 3'd3,\n    DONE_ST   = 3'd4;\n\nreg [2:0] state;\nreg [3:0] queue [0:15];\nreg [4:0] q_head, q_tail;\nreg [7:0] dist_iron [0:15];\nreg [7:0] dist_coal [0:15];\nreg [15:0] visited;\nreg [3:0] current_node;\nreg [3:0] target_idx;\nreg [7:0] min_settlers;\nreg [7:0] cycle_count;\n\ninteger i;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        impossible <= 1'b0;\n        result <= 8'd0;\n        q_head <= 5'd0;\n        q_tail <= 5'd0;\n        visited <= 16'd0;\n        min_settlers <= 8'hFF;\n        cycle_count <= 8'd0;\n        \n        for (i = 0; i < 16; i = i + 1) begin\n            dist_iron[i] <= 8'hFF;\n            dist_coal[i] <= 8'hFF;\n        end\n        \n        for (i = 0; i < 16; i = i + 1) begin\n            queue[i] <= 4'd0;\n        end\n    end else begin\n        cycle_count <= cycle_count + 8'd1;\n        \n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                min_settlers <= 8'hFF;\n                cycle_count <= 8'd0;\n                if (start) begin\n                    for (i = 0; i < 16; i = i + 1) begin\n                        dist_iron[i] <= 8'hFF;\n                        dist_coal[i] <= 8'hFF;\n                    end\n                    dist_iron[0] <= 8'd0;\n                    dist_coal[0] <= 8'd0;\n                    q_head <= 5'd0;\n                    q_tail <= 5'd1;\n                    queue[0] <= 4'd0;\n                    visited <= 16'd1;\n                    target_idx <= 4'd0;\n                    state <= BFS_IRON;\n                end\n            end\n            \n            BFS_IRON: begin\n                if (q_head < q_tail) begin\n                    current_node <= queue[q_head];\n                    q_head <= q_head + 5'd1;\n                    visited[current_node] <= 1'b1;\n                    \n                    for (i = 0; i < 16; i = i + 1) begin\n                        if (adjacency[current_node][i] && !visited[i]) begin\n                            visited[i] <= 1'b1;\n                            dist_iron[i] <= dist_iron[current_node] + 8'd1;\n                            queue[q_tail] <= i;\n                            q_tail <= q_tail + 5'd1;\n                        end\n                    end\n                end else begin\n                    if (target_idx < iron_count) begin\n                        if (dist_iron[iron_nodes[target_idx]] != 8'hFF) begin\n                            target_idx <= target_idx + 4'd1;\n                        end\n                    end else begin\n                        q_head <= 5'd0;\n                        q_tail <= 5'd1;\n                        queue[0] <= 4'd0;\n                        visited <= 16'd1;\n                        target_idx <= 4'd0;\n                        state <= BFS_COAL;\n                    end\n                end\n            end\n            \n            BFS_COAL: begin\n                if (q_head < q_tail) begin\n                    current_node <= queue[q_head];\n                    q_head <= q_head + 5'd1;\n                    visited[current_node] <= 1'b1;\n                    \n                    for (i = 0; i < 16; i = i + 1) begin\n                        if (adjacency[current_node][i] && !visited[i]) begin\n                            visited[i] <= 1'b1;\n                            dist_coal[i] <= dist_coal[current_node] + 8'd1;\n                            queue[q_tail] <= i;\n                            q_tail <= q_tail + 5'd1;\n                        end\n                    end\n                end else begin\n                    if (target_idx < coal_count) begin\n                        if (dist_coal[coal_nodes[target_idx]] != 8'hFF) begin\n                            target_idx <= target_idx + 4'd1;\n                        end\n                    end else begin\n                        state <= COMPUTE;\n                    end\n                end\n            end\n            \n            COMPUTE: begin\n                for (i = 0; i < 4; i = i + 1) begin\n                    if (i < iron_count && dist_iron[iron_nodes[i]] != 8'hFF) begin\n                        integer j;\n                        for (j = 0; j < 4; j = j + 1) begin\n                            if (j < coal_count && dist_coal[coal_nodes[j]] != 8'hFF) begin\n                                reg [7:0] total;\n                                total = dist_iron[iron_nodes[i]] + dist_coal[coal_nodes[j]] - 8'd1;\n                                if (total < min_settlers) begin\n                                    min_settlers <= total;\n                                end\n                            end\n                        end\n                    end\n                end\n                \n                if (min_settlers == 8'hFF) begin\n                    impossible <= 1'b1;\n                    result <= 8'd0;\n                end else begin\n                    result <= min_settlers;\n                    impossible <= 1'b0;\n                end\n                state <= DONE_ST;\n            end\n            \n            DONE_ST: begin\n                done <= 1'b1;\n                if (!start) state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule